<script lang="ts">
 import {onMount} from 'svelte';import {api,type ProblemDetail,type User} from './api';import DOMPurify from 'dompurify';import {marked} from 'marked';
 export let problem:ProblemDetail;export let user:User;export let onerror:(e:string)=>void;
 let host:HTMLDivElement, language:'cpp'|'python'='cpp',editor:any,monaco:any,semantic='Starting editor…',busy=false,result:any=null,history:any[]=[],custom='',tab='results',alive=true,subscription:any,disconnect:(()=>void)|undefined;
 const key=()=>`practice:${user.id}:${problem.version}:${language}`;
 const statement=DOMPurify.sanitize(marked.parse(problem.problem.statement,{async:false}) as string);
 function save(){if(editor)localStorage.setItem(key(),editor.getValue())}
 async function connect(){disconnect?.();semantic='Connecting semantic completion…';try{const lsp=await import('./semantic');disconnect=await lsp.connect(monaco,editor,language,(s:string)=>semantic=s)}catch{semantic='Basic completion · semantic service unavailable'}}
 async function change(){disconnect?.();const old=editor.getModel();const model=monaco.editor.createModel(localStorage.getItem(key())||problem.starters[language],language==='cpp'?'cpp':'python',monaco.Uri.parse(`file:///workspace/solution.${language==='cpp'?'cpp':'py'}`));editor.setModel(model);old?.dispose();await connect()}
 async function historyLoad(){history=await api(`/submissions?version=${problem.version}`)}
 onMount(()=>{alive=true;(async()=>{try{const setup=await import('./monaco');await setup.initialize();monaco=setup.monaco;editor=monaco.editor.create(host,{value:localStorage.getItem(key())||problem.starters[language],language:'cpp',theme:'vs-dark',automaticLayout:true,minimap:{enabled:false},fontSize:14,padding:{top:18},scrollBeyondLastLine:false});subscription=editor.onDidChangeModelContent(save);await change();await historyLoad()}catch(e){onerror(String(e))}})();return()=>{alive=false;save();disconnect?.();subscription?.dispose();editor?.getModel()?.dispose();editor?.dispose()}});
 async function execute(mode:string){busy=true;result=null;tab='results';try{save();let cases;if(mode==='run'&&custom.trim()){cases=JSON.parse(custom);if(!Array.isArray(cases))throw new Error('Custom cases must be an array of {args, expected?} objects')}const r=await api('/submissions','POST',{version:problem.version,language,source:editor.getValue(),mode,...(cases?{cases}:{})},crypto.randomUUID());for(let count=0;alive&&count<4000;count++){const s=await api(`/submissions/${r.id}`);if(s.status==='completed'){result=s.result;break}semantic=semantic;await new Promise(resolve=>setTimeout(resolve,1000))}await historyLoad()}catch(e){onerror(String(e))}finally{busy=false}}
</script>
<div class="workspace"><section class="statement-pane"><div class="eyebrow">PROBLEM / {problem.problem.difficulty.toUpperCase()}</div><h1>{problem.problem.title}</h1><div class="tags">{#each problem.problem.tags as tag}<span>{tag}</span>{/each}</div><article class="statement">{@html statement}</article><h3>Examples</h3>{#each problem.problem.tests as t,i}<div class="example"><b>Example {i+1}</b><pre>Arguments: {JSON.stringify(t.args)}<br/>Expected:  {JSON.stringify(t.expected)}</pre></div>{/each}<p class="muted small">{problem.problem.limits.time_ms} ms · {problem.problem.limits.memory_mib} MiB per test<br/>Standard libraries · Solution class method</p></section><section class="code-pane"><div class="editor-toolbar"><label class="sr-only" for="language">Language</label><select id="language" value={language} onchange={async(e)=>{save();language=e.currentTarget.value as 'cpp'|'python';await change()}} disabled={busy}><option value="cpp">C++20</option><option value="python">Python 3</option></select><span>solution.{language==='cpp'?'cpp':'py'}</span><div class="actions"><button onclick={()=>execute('run')} disabled={busy||!editor}>▷ Run</button><button class="primary" onclick={()=>execute('submit')} disabled={busy||!editor}>{busy?'Judging…':'Submit →'}</button></div></div><div class="monaco-host" bind:this={host}></div><div class="semantic" role="status">● {semantic}<button onclick={connect}>Reconnect</button></div><div class="results"><div class="toolbar"><button class:chosen={tab==='results'} onclick={()=>tab='results'}>Results</button><button class:chosen={tab==='custom'} onclick={()=>tab='custom'}>Custom tests</button><button class:chosen={tab==='history'} onclick={()=>{tab='history';historyLoad()}}>History</button></div>{#if tab==='custom'}<label>JSON cases (expected is optional)<textarea bind:value={custom} placeholder={'[{"args": [[1, 2]], "expected": 3}]'} spellcheck="false"></textarea></label>{:else if tab==='history'}{#each history as h}<button class="history" onclick={()=>{result=h.result;tab='results'}}>{h.language} · {h.mode}<span>{h.result?.verdict||h.status}</span><small>{new Date(h.created_at).toLocaleString()}</small></button>{:else}<p class="muted">Your submissions will appear here.</p>{/each}{:else if busy}<p role="status">Your solution is queued or running…</p>{:else if result}<h3 class:notice={result.verdict==='accepted'}>{result.cases.length && result.cases.every((c:any)=>c.verdict===null)?'Output only':result.verdict.replaceAll('_',' ')} {#if !result.cases.length || result.cases.some((c:any)=>c.verdict!==null)}<small>{result.passed} / {result.total} passed</small>{/if}</h3>{#if result.diagnostic}<pre>{result.diagnostic}</pre>{/if}{#each result.cases as c,i}<div class="case"><b>Visible case {i+1}: {c.verdict?.replaceAll('_',' ')||'Output only'}</b>{#if c.output!==null}<pre>{JSON.stringify(c.output)}</pre>{/if}{#if c.log}<pre>{c.log}</pre>{/if}</div>{/each}<p class="muted small">Hidden cases contribute only to the verdict and pass count.</p>{:else}<p class="muted">Run examples to explore your solution, or submit to judge all tests.</p>{/if}</div></section></div>
